import {seeds,kinds} from './catalog.js';
import {plain,norm,safeURL,licenseName,searchArchive,searchCommons,translatedTitle,resolveItem} from './providers.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const write=(key,val)=>{try{localStorage.setItem(key,JSON.stringify(val))}catch{}};
const validItem=x=>x&&typeof x.id==='string'&&['archive','commons'].includes(x.provider)&&typeof x.ref==='string';
const snapshot=x=>{const {videoInfo,...rest}=x;return rest};
const items=new Map(seeds.map(x=>[x.id,x]));
const storedSaved=read('kinoteka-saved-v2',null);const saved=new Map((Array.isArray(storedSaved)?storedSaved:[]).filter(validItem).map(x=>[x.id,x]));
for(const old of read('kinoteka-saved',[])){const seed=seeds.find(s=>s.legacy===old);if(seed&&storedSaved===null)saved.set(seed.id,seed)}
const storedHistory=read('kinoteka-history-v2',{});const history=storedHistory&&typeof storedHistory==='object'&&!Array.isArray(storedHistory)?storedHistory:{};
for(const [id,pos] of Object.entries(read('kinoteka-positions',{}))){const s=seeds.find(x=>x.legacy===id);if(s&&pos>5&&!history[s.id])history[s.id]={item:s,time:pos,duration:s.duration||0,updated:Date.now()}}
for(const x of saved.values())items.set(x.id,{...x,...items.get(x.id)});
for(const h of Object.values(history))if(validItem(h.item))items.set(h.item.id,{...h.item,...items.get(h.item.id)});
let view='home',kind='all',query='',provider='all',sort='relevance',page=1,results=[],more=false,searchSeq=0,searchController=null,searchTimer=null,busy=false;
const status={archive:null,commons:null};const searchCache=new Map(),titleCache=new Map(),resolvedCache=new Map();
let detailItem=null,detailData=null,detailController=null,detailSeq=0,toastTimer;
let session=null,videoSerial=0,qualitySwitch=false,lastPersist=0,failedSources=new Set();
const v=$('#video');
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2600)}
function getCover(x){return esc(safeURL(x.poster,['archive.org','wikimedia.org'])||(x.poster?.startsWith('assets/')?x.poster:'assets/cover.svg'))}
function installCoverFallbacks(){document.querySelectorAll('img[data-cover]').forEach(img=>{img.onerror=()=>{if(img.dataset.fallback)return;img.dataset.fallback='1';img.src='assets/cover.svg'}})}
function time(sec){if(!Number.isFinite(sec)||sec<0)return '0:00';const n=Math.floor(sec);return n>=3600?Math.floor(n/3600)+':'+String(Math.floor(n/60)%60).padStart(2,'0')+':'+String(n%60).padStart(2,'0'):Math.floor(n/60)+':'+String(n%60).padStart(2,'0')}
function plural(n,one,few,many){const a=n%100,b=n%10;return n+' '+(a>=11&&a<=14?many:b===1?one:b>=2&&b<=4?few:many)}
function duration(sec){if(!sec)return '';const m=Math.round(sec/60);return m>=60?Math.floor(m/60)+' ч '+(m%60?m%60+' мин':''):m+' мин'}
function card(item){const label=kinds[item.kind]||'Видео';return `<article class="poster-card"><button class="poster-open" data-open="${esc(item.id)}" aria-label="Открыть: ${esc(item.title)}"><img data-cover loading="lazy" src="${getCover(item)}" alt="Обложка: ${esc(item.title)}"><span class="poster-shade"></span><span class="provider-pill">${item.provider==='commons'?'WIKIMEDIA':'ARCHIVE'}</span><span class="poster-lettering">${esc(item.original||item.title)}</span><span class="card-play">${icon('play')}</span></button><button class="card-save icon-button" data-save="${esc(item.id)}" aria-label="${saved.has(item.id)?'Убрать из списка':'Сохранить'}: ${esc(item.title)}" aria-pressed="${saved.has(item.id)}">${icon(saved.has(item.id)?'check':'plus')}</button><h3 title="${esc(item.title)}">${esc(item.title)}</h3><p class="card-meta">${esc([item.year,label,duration(item.duration)].filter(Boolean).join(' · '))}</p></article>`}
function renderChips(){for(const id of ['home-types','catalog-types']){$('#'+id).innerHTML=Object.entries(kinds).map(([k,label])=>`<button class="chip ${(id==='home-types'?k==='all':kind===k)?'active':''}" data-kind="${k}" aria-pressed="${id==='home-types'?k==='all':kind===k}">${label}</button>`).join('')}}
function renderHome(){$('#picks-grid').innerHTML=seeds.slice(0,6).map(card).join('');$('#series-grid').innerHTML=seeds.filter(s=>['series','animatedSeries'].includes(s.kind)).map(card).join('');const recent=Object.values(history).filter(h=>validItem(h.item)&&h.time>5&&!h.finished).sort((a,b)=>b.updated-a.updated).slice(0,3);$('#continue-section').hidden=!recent.length;$('#continue-grid').innerHTML=recent.map(h=>`<article class="continue-card"><button data-resume="${esc(h.item.id)}"><img data-cover src="${getCover(h.item)}" alt="${esc(h.item.title)}"><div><h3>${esc(h.item.title)}</h3><p>${h.episodeTitle&&h.episodeTitle!==h.item.title?esc(h.episodeTitle).slice(0,45)+' · ':''}${time(h.time)}${h.duration?' из '+time(h.duration):''}</p></div></button><div class="progress"><span style="width:${Math.min(100,h.time/(h.duration||1)*100)}%"></span></div></article>`).join('');const b=$('.hero-save');b.innerHTML=icon(saved.has('ia:Sintel')?'check':'plus');b.setAttribute('aria-label',saved.has('ia:Sintel')?'Убрать Синтел из списка':'Добавить Синтел в мой список');b.setAttribute('aria-pressed',saved.has('ia:Sintel'));installCoverFallbacks()}
function updateSaved(){write('kinoteka-saved-v2',[...saved.values()].map(snapshot));$('#saved-count').textContent=saved.size;document.querySelectorAll('[data-save]').forEach(b=>{const yes=saved.has(b.dataset.save);b.setAttribute('aria-pressed',yes);b.innerHTML=icon(yes?'check':'plus')+(b.classList.contains('detail-save')?(yes?'В списке':'Мой список'):'')})}
function toggleSave(id){const item=items.get(id);if(!item)return;if(saved.has(id)){saved.delete(id);toast('Убрано из моего списка')}else{saved.set(id,snapshot(item));toast('Добавлено в мой список')}updateSaved();if(view==='saved')renderCatalog()}
function localMatches(x){if(kind!=='all'&&x.kind!==kind)return false;if(provider!=='all'&&x.provider!==provider)return false;const text=norm([x.title,x.original,x.genre,x.year].join(' '));return !query||norm(query).split(/\s+/).every(w=>text.includes(w))}
function unique(list){const ids=new Set(),titles=new Set();return list.filter(x=>{const key=norm(x.original||x.title).replace(/[^a-zа-я0-9]/g,'');if(ids.has(x.id)||(key&&titles.has(key)))return false;ids.add(x.id);titles.add(key);return true})}
function sorted(list){return sort==='new'?list.sort((a,b)=>(Number(b.year)||0)-(Number(a.year)||0)):sort==='old'?list.sort((a,b)=>(Number(a.year)||9999)-(Number(b.year)||9999)):list}
function visibleItems(){if(view==='saved')return sorted([...saved.values()].filter(localMatches));if(view==='history')return Object.values(history).filter(h=>validItem(h.item)).sort((a,b)=>b.updated-a.updated).map(h=>h.item).filter(localMatches);return sorted(unique(results).filter(x=>(kind==='all'||x.kind===kind)&&(provider==='all'||provider===x.provider)))}
function renderStatus(){const parts=[];if(!['saved','history'].includes(view))for(const [key,label] of [['archive','Internet Archive'],['commons','Wikimedia Commons']]){if(provider!=='all'&&provider!==key)continue;const s=status[key];if(s?.state==='busy')parts.push(`<span class="busy">${label} · поиск</span>`);if(s?.state==='ready')parts.push(`<span class="ready">${label} · ${plural(s.count,'запись','записи','записей')}</span>`);if(s?.state==='failed')parts.push(`<span class="failed">${label} · ${esc(s.message)}</span>`)}$('#provider-status').innerHTML=parts.join('')}
function renderCatalog(){const list=visibleItems();$('#results-grid').innerHTML=list.map(card).join('');$('#results-label').textContent=busy?`Ищем в источниках · уже ${list.length} записей`:`${view==='saved'?'В моём списке':view==='history'?'В истории':'Показано'}: ${list.length}${query?' · «'+query+'»':''}`;$('#empty-state').hidden=!!list.length||busy;const empty=$('#empty-state h2');empty.textContent=view==='saved'?'Сохраните что-нибудь на вечер':view==='history'?'Здесь будет ваша история':'Пока ничего не нашлось';$('#empty-copy').textContent=view==='saved'?'Нажмите + на обложке — фильм появится в вашем списке.':view==='history'?'Начните смотреть фильм или серию, и мы запомним место.':Object.values(status).some(s=>s?.state==='failed')?'Не все источники ответили. Попробуйте повторить поиск или выбрать другой источник.':'Попробуйте оригинальное название или другой тип видео. Поиск показывает только записи с открытой лицензией; не каждый фильм доступен бесплатно.';$('#reset-filters').textContent=['saved','history'].includes(view)?'Открыть каталог':'Сбросить фильтры';$('#load-more').hidden=!more||['saved','history'].includes(view);$('#load-more').disabled=busy;$('#load-more').textContent=busy?'Загружаем…':'Показать ещё';renderStatus();installCoverFallbacks()}
function renderView(){const home=view==='home';$('#home-view').hidden=!home;$('#catalog-view').hidden=home;document.querySelectorAll('[data-nav]').forEach(b=>{const is=b.dataset.nav===view||view==='catalog'&&b.dataset.nav===kind&&kind!=='all';b.classList.toggle('active',is);if(is)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#catalog-title').textContent=view==='saved'?'Мой список':view==='history'?'История просмотра':query?'Поиск «'+query+'»':kind==='all'?'Весь каталог':kinds[kind];$('#catalog-eyebrow').textContent=['saved','history'].includes(view)?'МОЯ КИНОТЕКА':'ПОИСК ПО ВНЕШНИМ ИСТОЧНИКАМ';$('#clear-search').hidden=!$('#search').value;renderChips();updateSaved();home?renderHome():renderCatalog()}
function go(target,{keepQuery=false,scroll=true}={}){clearTimeout(searchTimer);if(['film','animation','series','animatedSeries'].includes(target)){view='catalog';kind=target}else{view=target;kind='all'}if(!keepQuery){query='';$('#search').value=''}if(['saved','history','home'].includes(view)){searchController?.abort();searchSeq++;busy=false;more=false}else{provider=$('#provider').value;runSearch(false)}renderView();if(scroll)window.scrollTo({top:0,behavior:'instant'});const route=view==='catalog'?kind==='all'?'catalog':kind:view;if(location.hash!=='#'+route)historyRoute(route)}
function historyRoute(route){const p=new URLSearchParams();if(!['home','saved','history'].includes(route)){if(query)p.set('q',query);if(provider!=='all')p.set('source',provider);if(sort!=='relevance')p.set('sort',sort)}window.history.replaceState(null,'','#'+route+(p.size?'?'+p.toString():''))}
async function cachedSearch(key,fn){const hit=searchCache.get(key);if(hit&&Date.now()-hit.at<300000)return hit.value;const value=await fn();searchCache.set(key,{at:Date.now(),value});if(searchCache.size>35)searchCache.delete(searchCache.keys().next().value);return value}
async function runSearch(append=false){if(view==='catalog')historyRoute(kind==='all'?'catalog':kind);searchController?.abort();searchController=new AbortController();const signal=searchController.signal,seq=++searchSeq;page=append?page+1:1;const reqPage=page;busy=true;more=false;const local=query?seeds.filter(localMatches):seeds.filter(localMatches);if(!append)results=[...local];status.archive=provider==='commons'?null:{state:'busy'};status.commons=provider==='archive'?null:{state:'busy'};renderCatalog();let translated='';if(query){if(titleCache.has(query))translated=titleCache.get(query);else{translated=await translatedTitle(query,signal);if(!signal.aborted)titleCache.set(query,translated)}}if(signal.aborted||seq!==searchSeq)return;const args={q:query,translated,kind,page:reqPage,sort,signal};let canMore=false;const tasks=[];for(const [key,fn] of [['archive',searchArchive],['commons',searchCommons]]){if(provider!=='all'&&provider!==key)continue;const cacheKey=JSON.stringify([key,query,translated,kind,sort,reqPage]);tasks.push((async()=>{try{const data=await cachedSearch(cacheKey,()=>fn(args));if(seq!==searchSeq||signal.aborted)return;for(const x of data.items){items.set(x.id,{...items.get(x.id),...x});results.push(items.get(x.id))}status[key]={state:'ready',count:data.items.length};if(key==='archive'?data.total>reqPage*24:data.more)canMore=true;renderCatalog()}catch(e){if(seq!==searchSeq||signal.aborted)return;status[key]={state:'failed',message:e.name==='AbortError'?'не ответил вовремя':e.message||'недоступен'};renderCatalog()}})())}await Promise.allSettled(tasks);if(seq!==searchSeq||signal.aborted)return;busy=false;more=canMore;renderCatalog()}
function submitSearch(){query=$('#search').value.trim().slice(0,150);clearTimeout(searchTimer);if(view!=='catalog'){view='catalog';kind='all'}historyRoute(kind==='all'?'catalog':kind);renderView();runSearch(false)}
function detailMarkup(item){return `<div class="detail-layout"><img class="detail-poster" data-cover src="${getCover(item)}" alt="Обложка: ${esc(item.title)}"><div class="detail-body"><p class="eyebrow">${esc(kinds[item.kind]||'ВИДЕО')}</p><h2 id="detail-title">${esc(item.title)}</h2><p class="detail-original">${esc(item.original||'')}</p><p class="detail-meta">${esc([item.year,item.genre,duration(item.duration)].filter(Boolean).join(' · '))}</p><p class="detail-desc">${esc(item.description||'Описание будет загружено из источника. Подробная информация об этой записи доступна по ссылке ниже.')}</p><div class="detail-buttons"><button id="detail-watch" class="primary" disabled>${icon('play')}Подключаем…</button><button class="secondary detail-save" data-save="${esc(item.id)}" aria-pressed="${saved.has(item.id)}">${icon(saved.has(item.id)?'check':'plus')}${saved.has(item.id)?'В списке':'Мой список'}</button></div><p class="detail-status" id="detail-status">Проверяем видео и доступное качество</p><div class="detail-source" id="detail-source"></div></div></div><div class="episode-preview" id="episode-preview" hidden></div>`}
function sourceMarkup(item,data){const url=safeURL(data?.source||item.source||'https://archive.org/details/'+encodeURIComponent(item.ref),['archive.org','wikimedia.org']);const license=safeURL(data?.license||item.license,['creativecommons.org']);return `<a href="${esc(url)}" target="_blank" rel="noopener">${url.includes('wikimedia.org')?'Wikimedia Commons':'Internet Archive'} ↗</a>${license?` · <a class="license-link" href="${esc(license)}" target="_blank" rel="noopener">${esc(licenseName(license))}</a>`:''}<p>${esc(data?.creator||item.creator||'Автор указан в источнике')}<br>${esc(data?.language||item.language||'Язык зависит от записи.')} · Лицензия указана источником.</p>${data?.alternateSource?'<a href="'+esc(safeURL(data.alternateSource,['wikimedia.org']))+'" target="_blank" rel="noopener">Дополнительные версии · Wikimedia Commons ↗</a>':''}`}
async function resolveCached(item,signal){if(resolvedCache.has(item.id))return resolvedCache.get(item.id);const data=await resolveItem(item,signal);if(signal?.aborted)throw new DOMException('Aborted','AbortError');resolvedCache.set(item.id,data);return data}
async function openDetail(id,{autoplay=false,resume=false}={}){const item=items.get(id);if(!item)return;detailController?.abort();detailController=new AbortController();const seq=++detailSeq;detailItem=item;detailData=null;$('#detail-content').innerHTML=detailMarkup(item);if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#detail-source').innerHTML=sourceMarkup(item);installCoverFallbacks();try{const data=await resolveCached(item,detailController.signal);if(seq!==detailSeq)return;detailData=data;const count=data.episodes.length;$('#detail-watch').disabled=false;$('#detail-watch').innerHTML=icon('play')+(history[item.id]?.time>5?'Продолжить':'Смотреть');$('#detail-status').textContent=`${count>1?plural(count,'серия','серии','серий')+' · ':''}${data.episodes[0].sources.length>1?'Доступен выбор качества':'Одна доступная видеоверсия'}`;$('#detail-source').innerHTML=sourceMarkup(item,data);if(count>1){$('#episode-preview').hidden=false;$('#episode-preview').innerHTML='<h3>Серии в источнике · '+count+'</h3>'+data.episodes.map((e,i)=>`<button data-episode-start="${i}"><span class="ep-index">${String(i+1).padStart(2,'0')}</span><span>${esc(e.title)}</span><span class="ep-runtime">${duration(e.duration)}</span>${icon('play')}</button>`).join('')}if(autoplay||resume)startPlayer(undefined,true)}catch(e){if(seq!==detailSeq||detailController.signal.aborted)return;$('#detail-watch').textContent='Повторить проверку';$('#detail-watch').disabled=false;$('#detail-watch').dataset.retry='true';$('#detail-status').classList.add('error');$('#detail-status').textContent=e.name==='AbortError'?'Источник не ответил вовремя. Попробуйте ещё раз.':e.message}}
function closeDetail(){detailSeq++;detailController?.abort();$('#detail-dialog').close()}
function playableSources(ep){const s=ep.sources.filter(s=>v.canPlayType(s.type));return (s.length?s:ep.sources.filter(s=>s.type==='video/mp4')).sort((a,b)=>b.height-a.height)}
function startPlayer(index,autoplay=false){if(!detailData||!detailItem)return;const prev=history[detailItem.id];let epIndex=index??Math.max(0,detailData.episodes.findIndex(e=>e.id===prev?.episodeId));session={item:detailItem,data:detailData,index:epIndex,sources:[],sourceIndex:0,trackTime:0};$('#detail-dialog').close();detailSeq++;detailController?.abort();$('#player-title').textContent=session.item.title;$('#player-attribution').innerHTML=sourceMarkup(session.item,session.data);$('#autonext').checked=read('kinoteka-autonext',true);$('#episode-panel').hidden=detailData.episodes.length<2;$('#autonext').closest('label').hidden=detailData.episodes.length<2;$('#episode-count').textContent=detailData.episodes.length;$('#episode-list').innerHTML=detailData.episodes.map((e,i)=>`<button data-player-episode="${i}"><span class="ep-num">${String(i+1).padStart(2,'0')}</span><span>${esc(e.title)}<br><small>${duration(e.duration)}</small></span></button>`).join('');if(!$('#player-dialog').open)$('#player-dialog').showModal();v.controls=false;$('#video-controls').hidden=false;loadEpisode(epIndex,autoplay,index===undefined?prev?.time||0:0)}
function chooseInitial(sources){const pref=Number(read('kinoteka-quality',0));if(pref>0){const exact=sources.findIndex(s=>s.height===pref);if(exact>=0)return exact}const medium=sources.findIndex(s=>s.height>0&&s.height<=720);return medium>=0?medium:Math.max(0,sources.findIndex(s=>s.type==='video/mp4'))}
function loadEpisode(index,autoplay=false,resumeAt=0){if(!session)return;session.index=index;const ep=session.data.episodes[index];session.sources=playableSources(ep);session.sourceIndex=chooseInitial(session.sources);failedSources.clear();$('#episode-title').textContent=session.data.episodes.length>1?ep.title:session.item.original||'';$('#episode-list').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===index));$('#next-episode').hidden=index>=session.data.episodes.length-1;$('#quality').innerHTML=session.sources.map((s,i)=>`<option value="${i}">${esc(s.label+' · '+(s.type.includes('webm')?'WebM':'MP4'))}</option>`).join('');if(!session.sources.length){$('#play-status').textContent='Браузер не поддерживает форматы этой записи. Откройте источник ниже.';$('#video-loader').hidden=true;$('#center-play').hidden=true;return}setSource(session.sourceIndex,resumeAt,autoplay)}
function setSource(index,at=0,autoplay=false){if(!session)return;qualitySwitch=true;const serial=++videoSerial;session.sourceIndex=index;const source=session.sources[index];$('#quality').value=index;$('#stream-provider').textContent=source.provider;$('#video-loader').hidden=false;$('#video-loader-text').textContent='Подключаем видео';$('#center-play').hidden=true;$('#play-status').textContent='';$('#retry-video').hidden=true;const speed=Number($('#speed').value);v.pause();v.src=source.url;v.poster=session.item.poster||'';v.load();const ready=()=>{if(!session||serial!==videoSerial)return;qualitySwitch=false;if(at>0&&Number.isFinite(v.duration))v.currentTime=Math.min(at,Math.max(0,v.duration-1));v.playbackRate=speed;$('#video-loader').hidden=true;$('#center-play').hidden=autoplay;updateControls();if(autoplay)v.play().catch(()=>{$('#center-play').hidden=false;$('#play-status').textContent='Нажмите кнопку воспроизведения, чтобы начать.'})};v.addEventListener('loadedmetadata',ready,{once:true});}
function persist(finished=false){if(!session||qualitySwitch||!Number.isFinite(v.currentTime)||v.currentTime<.1)return;const ep=session.data.episodes[session.index];history[session.item.id]={item:snapshot(session.item),episodeId:ep.id,episodeTitle:ep.title,time:finished?0:v.currentTime,duration:v.duration||ep.duration||0,updated:Date.now(),finished};const ordered=Object.entries(history).sort((a,b)=>b[1].updated-a[1].updated);write('kinoteka-history-v2',Object.fromEntries(ordered.slice(0,100)))}
function updateControls(){const playing=!v.paused&&!v.ended;$('#toggle-play').innerHTML=icon(playing?'pause':'play');$('#toggle-play').setAttribute('aria-label',playing?'Пауза':'Воспроизвести');$('#center-play').hidden=playing||!$('#video-loader').hidden;$('#video-stage').classList.toggle('is-playing',playing);$('#time-label').textContent=time(v.currentTime)+' / '+time(v.duration);$('#seek').value=v.duration>0?v.currentTime/v.duration*100:0;$('#mute').innerHTML=icon(v.muted||v.volume===0?'mute':'volume');$('#mute').setAttribute('aria-label',v.muted?'Включить звук':'Выключить звук')}
async function togglePlay(){if(!session)return;if(v.paused){try{await v.play()}catch{$('#play-status').textContent='Не удалось запустить эту версию видео. Выберите другое качество или откройте источник.'}}else v.pause();updateControls()}
function nextEpisode(){if(!session||session.index>=session.data.episodes.length-1)return;persist();loadEpisode(session.index+1,true)}
function closePlayer(){persist();videoSerial++;qualitySwitch=true;v.pause();v.removeAttribute('src');v.load();session=null;$('#player-dialog').close();qualitySwitch=false;renderHome();if(view==='history')renderCatalog()}
async function fullscreen(){try{const stage=$('#video-stage');if(document.fullscreenElement)await document.exitFullscreen();else if(stage.requestFullscreen)await stage.requestFullscreen();else if(v.webkitEnterFullscreen)v.webkitEnterFullscreen()}catch{toast('Полноэкранный режим недоступен')}}
function initEvents(){document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]'),chip=e.target.closest('[data-kind]'),save=e.target.closest('[data-save]'),open=e.target.closest('[data-open]'),resume=e.target.closest('[data-resume]'),ep=e.target.closest('[data-episode-start]'),pep=e.target.closest('[data-player-episode]');if(nav){go(nav.dataset.nav);return}if(chip){kind=chip.dataset.kind;if(view==='home'){view='catalog';query='';historyRoute(kind==='all'?'catalog':kind)}renderView();if(!['saved','history'].includes(view))runSearch(false);return}if(save){toggleSave(save.dataset.save);return}if(open){openDetail(open.dataset.open);return}if(resume){openDetail(resume.dataset.resume,{resume:true});return}if(ep){startPlayer(Number(ep.dataset.episodeStart),true);return}if(pep&&session){persist();loadEpisode(Number(pep.dataset.playerEpisode),true)}});$('#search-form').addEventListener('submit',e=>{e.preventDefault();submitSearch()});$('#search').addEventListener('input',()=>{$('#clear-search').hidden=!$('#search').value;clearTimeout(searchTimer);searchTimer=setTimeout(submitSearch,650)});$('#clear-search').onclick=()=>{$('#search').value='';submitSearch();$('#search').focus()};$('#provider').onchange=()=>{provider=$('#provider').value;renderView();if(!['saved','history'].includes(view))runSearch(false)};$('#sort').onchange=()=>{sort=$('#sort').value;if(!['saved','history'].includes(view))runSearch(false);else renderCatalog()};$('#load-more').onclick=()=>runSearch(true);$('#reset-filters').onclick=()=>{if(['saved','history'].includes(view)){go('catalog');return}kind='all';provider='all';$('#provider').value='all';query='';$('#search').value='';renderView();runSearch(false)};$('#detail-close').onclick=closeDetail;$('#detail-dialog').addEventListener('cancel',()=>{detailSeq++;detailController?.abort()});$('#detail-dialog').addEventListener('click',e=>{if(e.target.closest('#detail-watch')){if($('#detail-watch').dataset.retry){openDetail(detailItem.id);return}startPlayer(undefined,true)}});$('#player-close').onclick=closePlayer;$('#player-dialog').addEventListener('cancel',e=>{e.preventDefault();closePlayer()});$('#quality').onchange=()=>{if(!session)return;persist();const index=Number($('#quality').value);write('kinoteka-quality',session.sources[index].height);setSource(index,v.currentTime,!v.paused)};$('#toggle-play').onclick=togglePlay;$('#center-play').onclick=togglePlay;v.onclick=togglePlay;$('#rewind').onclick=()=>{v.currentTime=Math.max(0,v.currentTime-10)};$('#forward').onclick=()=>{if(Number.isFinite(v.duration))v.currentTime=Math.min(v.duration,v.currentTime+10)};$('#seek').oninput=()=>{if(Number.isFinite(v.duration))v.currentTime=Number($('#seek').value)/100*v.duration};$('#mute').onclick=()=>{v.muted=!v.muted;updateControls()};$('#volume').oninput=()=>{v.volume=Number($('#volume').value);v.muted=v.volume===0;updateControls()};$('#speed').onchange=()=>v.playbackRate=Number($('#speed').value);$('#fullscreen').onclick=fullscreen;$('#pip').hidden=!document.pictureInPictureEnabled;$('#pip').onclick=async()=>{try{if(document.pictureInPictureElement)await document.exitPictureInPicture();else await v.requestPictureInPicture()}catch{toast('Режим «картинка в картинке» недоступен')}};$('#next-episode').onclick=nextEpisode;$('#autonext').onchange=()=>write('kinoteka-autonext',$('#autonext').checked);$('#retry-video').onclick=()=>{if(!session)return;const i=session.sources.findIndex((_,i)=>!failedSources.has(i));if(i<0){setSource(session.sourceIndex,v.currentTime,true);return}setSource(i,v.currentTime,true)};for(const ev of ['play','pause','loadedmetadata','volumechange'])v.addEventListener(ev,updateControls);v.addEventListener('playing',()=>{$('#video-loader').hidden=true;$('#play-status').textContent='';updateControls()});v.addEventListener('waiting',()=>{if(!session)return;$('#video-loader').hidden=false;$('#video-loader-text').textContent='Буферизация';$('#center-play').hidden=true});v.addEventListener('canplay',()=>{$('#video-loader').hidden=true;updateControls()});v.addEventListener('pause',()=>persist());v.addEventListener('timeupdate',()=>{updateControls();if(Date.now()-lastPersist>4000){persist();lastPersist=Date.now()}});v.addEventListener('ended',()=>{persist(true);if($('#autonext').checked&&session?.index<session.data.episodes.length-1)loadEpisode(session.index+1,true)});v.addEventListener('error',()=>{if(!session||!v.getAttribute('src'))return;qualitySwitch=false;failedSources.add(session.sourceIndex);$('#video-loader').hidden=true;$('#center-play').hidden=true;$('#play-status').textContent='Эта версия видео недоступна или не поддерживается браузером. Попробуйте другую версию или откройте источник ниже.';$('#retry-video').hidden=false});document.addEventListener('keydown',e=>{if(!session||!$('#player-dialog').open||/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();togglePlay()}if(e.code==='ArrowLeft'){e.preventDefault();v.currentTime=Math.max(0,v.currentTime-10)}if(e.code==='ArrowRight'&&Number.isFinite(v.duration)){e.preventDefault();v.currentTime=Math.min(v.duration,v.currentTime+10)}if(e.code==='KeyF')fullscreen();if(e.code==='KeyM'){v.muted=!v.muted;updateControls()}});for(const b of ['source-info','footer-about'])$('#'+b).onclick=()=>$('#about-dialog').showModal();$('#about-close').onclick=()=>$('#about-dialog').close();document.querySelectorAll('a[href="#home"]').forEach(a=>a.onclick=e=>{e.preventDefault();go('home')});window.addEventListener('pagehide',()=>persist());window.addEventListener('hashchange',restoreRoute)}
function restoreRoute(){const [route,pstr]=location.hash.slice(1).split('?');if(!route||!['home','catalog','saved','history',...Object.keys(kinds)].includes(route))return;const p=new URLSearchParams(pstr||'');query=(p.get('q')||'').slice(0,150);$('#search').value=query;provider=['archive','commons'].includes(p.get('source'))?p.get('source'):'all';sort=['new','old'].includes(p.get('sort'))?p.get('sort'):'relevance';$('#provider').value=provider;$('#sort').value=sort;go(route,{keepQuery:true,scroll:false})}
initEvents();renderView();restoreRoute();
